mapper.select:
/* PlatformLocationMapper.selectOperatorMbl */
SELECT
    U.MBL_NO_ENC    AS mblNoEnc
    , U.MBL_NO_HMAC AS mblNoHmac
FROM TB_USER U
WHERE U.CMPNY_CD = #{cmpnyCd}
  AND U.USER_CD  = #{userCd}

mapper.insert:
/* PlatformLocationMapper.insertPlatformSmsAuth */
INSERT INTO TB_SMS_AUTH_CODE (
    MBL_NO_ENC
    , MBL_NO_HMAC
    , AUTH_CD
    , PURPOSE_CD
    , EXPIRED_AT
    , INSERT_NO
    , SEND_REF_KEY

    , SEND_IP_HASH
    , SEND_USER_CD
)
VALUES (
    #{mblNoEnc}
    , #{mblNoHmac}
    , #{certNo}
    , 'PLATFORM_LOCATION'
    , DATE_ADD(NOW(), INTERVAL 1 MINUTE)
    , #{gvUserCd}
    , #{sendRefKey}
    , #{sendIpHash}
    , #{gvUserCd}
)

mapper.update:
/* PlatformLocationMapper.updatePlatformSmsVerified */
UPDATE TB_SMS_AUTH_CODE
SET
    VERIFIED_YN   = 'Y'
    , UPDATE_NO   = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE 1=1
  AND SMS_ID      = #{smsId}
  AND MBL_NO_HMAC = #{mblNoHmac}
  AND AUTH_CD     = #{certNo}
  AND PURPOSE_CD  = 'PLATFORM_LOCATION'
  AND EXPIRED_AT  >=  NOW()
  AND VERIFIED_YN = 'N'
  AND FAIL_CNT  <  5

mapper.select:
/* PlatformLocationMapper.selectGpsList */ SELECT 'ATTD' AS srcType , G.USER_CD AS userCd , G.API_CALL_TIME AS measureTime , G.GPS_INFO_TYPE AS gpsInfoType , G.LAT_ENC AS latEnc , G.LON_ENC AS lonEnc , G.LAT AS lat , G.LON AS lon , G.ACCURACY AS accuracy , G.IS_MOCKED AS mockedYn , G.IP_ADDR AS ipAddr FROM TB_USER_ATTD_GPS G WHERE G.CMPNY_CD = #{cmpnyCd} AND G.SITE_CD = #{siteCd} AND G.API_CALL_DATE = #{date} UNION ALL SELECT 'TBM' AS srcType , A.USER_CD AS userCd
, DATE_FORMAT(CONVERT_TZ(A.ENTRY_AT, @@SESSION.time_zone, '+09:00'), '%H%i%s') AS measureTime , NULL AS gpsInfoType , A.ENTRY_GPS_LAT_ENC AS latEnc , A.ENTRY_GPS_LON_ENC AS lonEnc , A.ENTRY_GPS_LAT AS lat , A.ENTRY_GPS_LON AS lon , NULL AS accuracy , 'N' AS mockedYn , NULL AS ipAddr FROM TB_TBM_ATTENDANCE A INNER JOIN TB_TBM_SESSION S ON S.CMPNY_CD = A.CMPNY_CD AND S.SESSION_CD = A.SESSION_CD WHERE A.CMPNY_CD = #{cmpnyCd} AND S.SITE_CD = #{siteCd} AND A.DEL_YN = 'N' AND (A.ENTRY_GPS_LAT IS NOT NULL OR A.ENTRY_GPS_LAT_ENC IS NOT NULL)
AND DATE_FORMAT(CONVERT_TZ(A.ENTRY_AT, @@SESSION.time_zone, '+09:00'), '%Y%m%d') = #{date} ORDER BY measureTime ASC LIMIT 1001

mapper.insert:
/* PlatformLocationMapper.insertLocationAccessLog */
INSERT INTO TB_LOCATION_ACCESS_LOG (
    ACCESSOR_USER_CD
    , ACCESS_DTIME
    , TARGET_CMPNY_CD
    , TARGET_SITE_CD
    , TARGET_DATE
    , SMS_AUTH_ID
    , SMS_VERIFIED_AT
    , RESULT_CNT
    , CLIENT_IP
    , REMOTE_ADDR
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{accessorUserCd}
    , NOW()
    , #{targetCmpnyCd}
    , #{targetSiteCd}
    , #{targetDate}
    , #{smsAuthId}
    , #{smsVerifiedAt}
    , #{resultCnt}
    , #{clientIp}
    , #{remoteAddr}
    , #{accessorUserCd}
    , NOW()
)
